BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE r uuid; a uuid; b uuid; c uuid; c2 uuid; line_a uuid; line_b uuid; v integer; blocked boolean;
BEGIN
 INSERT INTO public.refurb_receptions(reception_number,reception_date,supplier,vat_scheme,supplier_invoice_nr) VALUES('TEST-SETTLE-'||gen_random_uuid(),current_date,'TEST SETTLEMENT','margin','TEST ONLY') RETURNING id INTO r;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,0,'RMA',10000) RETURNING id INTO a;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,1,'RMA',0) RETURNING id INTO b;
 c:=public.assign_reception_supplier_rma(r,array[a,b],NULL,false,false,'test@example.invalid');
 SELECT id INTO line_a FROM public.supplier_rma_items WHERE case_id=c AND reception_item_id=a;
 SELECT id INTO line_b FROM public.supplier_rma_items WHERE case_id=c AND reception_item_id=b;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 PERFORM public.manage_supplier_rma('update_item',jsonb_build_object('case_id',c,'version',v,'item_id',line_a,'expected_cents',10000,'received_cents',2500),'test@example.invalid');
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 PERFORM public.settle_supplier_rma('copy_item',jsonb_build_object('case_id',c,'version',v,'item_id',line_a),'test@example.invalid');
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE id=line_a AND received_cents=10000) THEN RAISE EXCEPTION 'Row arrow failed'; END IF;
 blocked:=false; BEGIN PERFORM public.settle_supplier_rma('copy_all',jsonb_build_object('case_id',c,'version',v),'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_CONFLICT' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Stale receipt update accepted'; END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 PERFORM public.manage_supplier_rma('update_item',jsonb_build_object('case_id',c,'version',v,'item_id',line_b,'expected_cents',0,'received_cents',500),'test@example.invalid');
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 PERFORM public.settle_supplier_rma('copy_all',jsonb_build_object('case_id',c,'version',v),'test@example.invalid');
 IF (SELECT sum(received_cents) FROM public.supplier_rma_items WHERE case_id=c)<>10000 OR NOT EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE id=line_b AND received_cents=0) THEN RAISE EXCEPTION 'Bulk arrow or zero receipt failed'; END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 blocked:=false; BEGIN PERFORM public.settle_supplier_rma('copy_item',jsonb_build_object('case_id',c,'version',v,'item_id',gen_random_uuid()),'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_ITEM_NOT_FOUND' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Foreign item receipt accepted'; END IF;
 blocked:=false; BEGIN PERFORM public.settle_supplier_rma('finalize',jsonb_build_object('case_id',c,'version',v),'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_CONFIRMATION_REQUIRED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Unconfirmed finalization accepted'; END IF;
 PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',c,'version',v,'stage','refunded'),'test@example.invalid');
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 PERFORM public.manage_supplier_rma('update_item',jsonb_build_object('case_id',c,'version',v,'item_id',line_a,'expected_cents',10000,'received_cents',5000),'test@example.invalid');
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 PERFORM public.settle_supplier_rma('copy_item',jsonb_build_object('case_id',c,'version',v,'item_id',line_a),'test@example.invalid');
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 blocked:=false; BEGIN PERFORM public.settle_supplier_rma('finalize',jsonb_build_object('case_id',c,'version',v,'confirmed',true),'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_FINAL_FIELDS_REQUIRED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Missing supplier numbers accepted'; END IF;
 PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',c,'version',v,'stage','refunded','supplier_reference','TEST-RMA-123','supplier_credit_note','  '),'test@example.invalid');
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 blocked:=false; BEGIN PERFORM public.settle_supplier_rma('finalize',jsonb_build_object('case_id',c,'version',v,'confirmed',true),'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_FINAL_FIELDS_REQUIRED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Whitespace credit note accepted'; END IF;
 PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',c,'version',v,'stage','refunded','supplier_reference','TEST-RMA-123','supplier_credit_note','TEST-CN-456'),'test@example.invalid');
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 PERFORM public.settle_supplier_rma('finalize',jsonb_build_object('case_id',c,'version',v,'confirmed',true),'test@example.invalid');
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_cases WHERE id=c AND stage='handled' AND finalized_at IS NOT NULL) OR EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE case_id=c AND active) THEN RAISE EXCEPTION 'Finalization incomplete'; END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 blocked:=false; BEGIN PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',c,'version',v,'stage','draft'),'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_FINALIZED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Final dossier reopened'; END IF;
 blocked:=false; BEGIN UPDATE public.supplier_rma_items SET received_cents=1 WHERE id=line_a; EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_FINALIZED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Final receipt edited'; END IF;
 blocked:=false; BEGIN PERFORM public.settle_supplier_rma('copy_all',jsonb_build_object('case_id',c,'version',v),'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_FINALIZED' THEN blocked:=true; ELSE RAISE; END IF; END;
 IF NOT blocked THEN RAISE EXCEPTION 'Final bulk action accepted'; END IF;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,2,'RMA',5000) RETURNING id INTO a;
 IF EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE reception_item_id=a) THEN RAISE EXCEPTION 'New article attached to handled dossier'; END IF;
 c2:=public.assign_reception_supplier_rma(r,array[a],NULL,false,false,'test@example.invalid');
 IF c2=c THEN RAISE EXCEPTION 'Handled dossier reused'; END IF;
 IF (SELECT count(*) FROM public.supplier_rma_history WHERE case_id=c AND event IN ('copy_item','copy_all','finalize'))<>4 THEN RAISE EXCEPTION 'Receipt/finalization audit missing'; END IF;
END $$;
ROLLBACK;
SELECT 'PASS: receipt row/bulk copy including zero, optimistic locks, membership, confirmation, immutable handling, later dossier and audit; fixtures rolled back' AS verification;
